// Builds lib/admin/playbooks.generated.ts from the two playbooks in docs/ so the admin portal shows exactly what is
// in the repo at BUILD time (no runtime fs reads: Vercel's Next 13.5 tracing skips includes for App routes).
//   node scripts/gen-playbooks.mjs            write the generated file (runs in `build` and `dev`)
// A missing source file is not an error: its entry is { markdown: null } and the page shows a "being written" state.
// If the docs folder itself is not available (an app-only checkout), the existing generated file is left alone.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(here, '../../..');
const OUT = path.resolve(here, '../lib/admin/playbooks.generated.ts');

export const PLAYBOOKS = {
  season: 'docs/design/brand/seasons/PLAYBOOK.md',
  social: 'docs/marketing/SOCIAL-PLAYBOOK.md',
};

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// "Last updated" = an explicit "Last updated: YYYY-MM-DD" line in the doc, else the file's last git commit date.
// A shallow clone (Vercel) only knows its tip commit, so there we show no date rather than a wrong one.
function lastUpdated(rel, md) {
  const m = md.match(/^\s*(?:\*\*)?last updated(?:\*\*)?:?\s*(\d{4}-\d{2}-\d{2})/im);
  if (m) return m[1];
  try {
    const git = (...args) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    if (git('rev-parse', '--is-shallow-repository') === 'true') return null;
    const d = git('log', '-1', '--format=%cs', '--', rel);
    return DATE.test(d) ? d : null;
  } catch {
    return null;
  }
}

export function buildPlaybooks(root = ROOT) {
  const out = {};
  for (const [key, rel] of Object.entries(PLAYBOOKS)) {
    const file = path.join(root, rel);
    if (!existsSync(file)) { out[key] = { path: rel, markdown: null, updated: null }; continue; }
    const markdown = readFileSync(file, 'utf8').replace(/\r\n?/g, '\n');
    out[key] = { path: rel, markdown, updated: lastUpdated(rel, markdown) };
  }
  return out;
}

export function renderModule(data) {
  return `// GENERATED by scripts/gen-playbooks.mjs (runs in build + dev) from the playbooks in docs/. Do not edit by hand.
export interface PlaybookDoc { path: string; markdown: string | null; updated: string | null }
export const PLAYBOOKS: { season: PlaybookDoc; social: PlaybookDoc } = ${JSON.stringify(data, null, 2)};
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (!existsSync(path.join(ROOT, 'docs'))) {
    console.warn('gen-playbooks: docs/ not found, keeping the existing generated file');
  } else {
    const data = buildPlaybooks();
    writeFileSync(OUT, renderModule(data));
    console.log(`gen-playbooks: season ${data.season.markdown ? `${(data.season.markdown.length / 1024).toFixed(0)}K` : 'missing'}, social ${data.social.markdown ? `${(data.social.markdown.length / 1024).toFixed(0)}K` : 'missing'}`);
  }
}
